<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Какие условия контракта по ГОЗ являются существенными?", "acceptedAnswer": {"@type": "Answer", "text": "Предмет, цена и её вид, идентификатор государственного контракта (ИГК), условие об отдельном счёте и режиме его использования, форма сопровождения (банковское или казначейское), обязанности по кооперации, сроки и порядок приёмки."}}, {"@type": "Question", "name": "Каким законом регулируется контракт по ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Общие условия — Федеральным законом № 44-ФЗ (статья 34), специальные требования гособоронзаказа — Федеральным законом от 29.12.2012 № 275-ФЗ «О государственном оборонном заказе». Часть условий приходит из типовых условий контрактов ГОЗ."}}, {"@type": "Question", "name": "Зачем в контракте ГОЗ отдельный счёт?", "acceptedAnswer": {"@type": "Answer", "text": "Чтобы обеспечить прослеживаемость средств: расчёты по контракту идут только через отдельный счёт с режимом использования, а назначение каждого платежа контролируется банком или казначейством."}}, {"@type": "Question", "name": "Чем банковское сопровождение ГОЗ отличается от казначейского?", "acceptedAnswer": {"@type": "Answer", "text": "При банковском сопровождении счёт открывается в уполномоченном банке, который контролирует расчёты. При казначейском — лицевой счёт в территориальном органе казначейства с санкционированием операций. По умолчанию для ГОЗ применяется банковское сопровождение, для отдельных контрактов — казначейское."}}, {"@type": "Question", "name": "Нужно ли указывать ИГК в контракте по ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Идентификатор государственного контракта указывают в номере контракта, в платёжных документах, во внутренних распоряжениях исполнителя и в договорах с соисполнителями. В ГОЗ применяется 25-значный идентификатор."}}, {"@type": "Question", "name": "Что будет, если нарушить режим отдельного счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Платежи не пройдут по режиму использования счёта, а нарушение существенных условий контракта может повлечь претензии заказчика и ответственность исполнителя."}}, {"@type": "Question", "name": "Должны ли соисполнители открывать отдельные счета?", "acceptedAnswer": {"@type": "Answer", "text": "Как правило, да: каждый участник кооперации открывает отдельный счёт под тот же контракт, а головной исполнитель уведомляет соисполнителей и переносит существенные условия ГОЗ в договоры с ними."}}, {"@type": "Question", "name": "Какой вид цены указывать в контракте ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Ориентировочную (уточняемую), фиксированную или возмещающую издержки — в зависимости от контракта. Вид цены и условия её перевода в фиксированную должны быть зафиксированы в контракте явно."}}, {"@type": "Question", "name": "Кто поможет проверить контракт по ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Проверку существенных условий, открытие нужного счёта и настройку расчётов можно передать на сопровождение. Эксперт сверит контракт по чек-листу и поможет не допустить нарушений. Оставьте заявку — разберём ваш контракт."}}, {"@type": "Question", "name": "Нужен ли отдельный счёт по каждому контракту или достаточно одного?", "acceptedAnswer": {"@type": "Answer", "text": "По каждому. Пункт 3 части 1 и пункт 3 части 2 статьи 8 № 275-ФЗ прямо говорят об обязательном условии открытия отдельного счёта для каждого контракта в рамках договора о банковском сопровождении с уполномоченным банком."}}, {"@type": "Question", "name": "Всегда ли соисполнителю нужно открывать отдельный счёт?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. По части 6 статьи 8 требования об отдельном счёте и договоре с уполномоченным банком не применяются к контрактам, расчёты по которым идут по подпунктам «б», «б.1» и «з» пункта 2 части 1 статьи 8.3, — например, при оплате расходов в пределах установленной месячной суммы или электроэнергии по регулируемым ценам."}}, {"@type": "Question", "name": "Какую сумму можно платить с отдельного счёта на обычный?", "acceptedAnswer": {"@type": "Answer", "text": "Подпункт «з» пункта 2 части 1 статьи 8.3 разрешает оплату расходов на сумму не более 5 млн рублей в месяц. Размер ежегодно увеличивается исходя из индекса потребительских цен, который публикует уполномоченный федеральный орган; актуальное значение проверяют на его официальном сайте."}}, {"@type": "Question", "name": "Когда можно вывести прибыль по контракту гособоронзаказа?", "acceptedAnswer": {"@type": "Answer", "text": "После исполнения контракта и представления в уполномоченный банк акта приёма-передачи товара, выполненных работ или оказанных услуг — в размере, согласованном сторонами при заключении контракта. Для головного исполнителя предусмотрен и вариант перечисления прибыли при частичном исполнении, если результат принят заказчиком и размер согласован с ним."}}, {"@type": "Question", "name": "Что происходит с отдельным счётом, когда контракт исполнен?", "acceptedAnswer": {"@type": "Answer", "text": "Головной исполнитель или исполнитель подаёт в банк заявление о закрытии счёта после полного исполнения государственного контракта и получения уведомления от банка. На списание средств при закрытии требования режима не распространяются."}}, {"@type": "Question", "name": "Обязательно ли условие о каталогизации?", "acceptedAnswer": {"@type": "Answer", "text": "Да, если товары подлежат каталогизации. Головной исполнитель обязан устанавливать в контрактах с исполнителями условие об обязательном включении сведений в федеральный каталог продукции для федеральных нужд (п. 21.2 ч. 1 ст. 8 в редакции Федерального закона от 27.11.2023 № 555-ФЗ)."}}, {"@type": "Question", "name": "Как быстро нужно раскрывать сведения о кооперации?", "acceptedAnswer": {"@type": "Answer", "text": "В течение пяти рабочих дней со дня получения запроса государственного заказчика, органа финансового мониторинга или уполномоченного банка. Состав сведений формализован: наименование, адрес, телефоны руководителя, идентификационный номер налогоплательщика и код причины постановки на учёт."}}, {"@type": "Question", "name": "Какие оговорки обязательно включать в договор с соисполнителем по ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Идентификатор государственного контракта с обязанностью указывать его в платежах и первичных документах, расчёты через отдельные счета в уполномоченном банке, соблюдение режима статей 8.3–8.4, запрет привлекать субподрядчиков без отдельного счёта, представление сведений о кооперации, раздельный учёт и каталогизацию продукции. Все они вырастают из статьи 8 закона № 275-ФЗ."}}, {"@type": "Question", "name": "Можно ли не переносить условия ГОЗ в договор с субподрядчиком, если он поставляет обычные комплектующие?", "acceptedAnswer": {"@type": "Answer", "text": "Нет, если договор входит в сопровождаемую сделку: обязанности по статье 8 распространяются на каждого исполнителя по цепочке кооперации. Исключения — только договоры, по которым отдельный счёт законом не требуется (регулируемые тарифы, электроэнергия, договоры ниже установленного порога и другие случаи, перечисленные в законе)."}}, {"@type": "Question", "name": "Что будет, если в договоре кооперации нет оговорки об ИГК?", "acceptedAnswer": {"@type": "Answer", "text": "Сам договор действителен, но платежи по нему упираются в режим счёта: банк списывает деньги с отдельного счёта только при указании идентификатора в распоряжении (п. 1 ч. 1 ст. 8.3 № 275-ФЗ), а головной исполнитель нарушает п. 4 ч. 1 ст. 8. Исправляют дополнительным соглашением с указанием идентификатора и переоформлением счетов."}}]}
</script>
